/** Code lines (1-based) generated by any of the given block ids, via CodegenResult.lineMap. */
export function linesForBlocks(lineMap: Record<number, string> | undefined, ids: ReadonlySet<string>): Set<number> {
  const out = new Set<number>();
  if (!lineMap || ids.size === 0) return out;
  for (const [line, id] of Object.entries(lineMap)) {
    if (ids.has(id)) out.add(Number(line));
  }
  return new Set([...out].sort((a, b) => a - b));
}
